.index-testimonial {
  background-color: var(--color-bg-light);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-accent);
}

.index-stars {
  color: #ffc107;
  font-size: 1rem;
  margin-bottom: var(--spacing-sm);
  display: block;
  letter-spacing: 0.1em;
}

.index-testimonial-text {
  font-style: italic;
  margin-bottom: var(--spacing-md);
  color: var(--color-text-dark);
}

.index-testimonial-author {
  font-size: 0.95rem;
  color: var(--color-primary-dark);
  margin-bottom: 0;
}

.index-pricing {
  background-color: var(--color-bg-light);
}

.index-price-card {
  background-color: var(--color-bg-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  position: relative;
  transition: var(--transition);
}

.index-price-card:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.index-price-card-featured {
  border: 2px solid var(--color-primary);
  transform: scale(1.02);
}

.index-price-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-accent);
  color: var(--color-text-dark);
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  white-space: nowrap;
}

.index-price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.index-price-list {
  list-style: none;
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.index-price-list li {
  padding: var(--spacing-xs) 0;
  padding-left: var(--spacing-md);
  position: relative;
}

.index-price-list li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-accent);
  font-weight: 700;
}

.index-price-card h3 {
  margin-bottom: var(--spacing-md);
}

.index-price-card .btn {
  width: 100%;
  margin-top: auto;
}

.index-shipping-note {
  text-align: center;
  margin-top: var(--spacing-xl);
  padding: var(--spacing-lg);
  background-color: var(--color-bg-white);
  border-radius: 8px;
  color: var(--color-text-dark);
}

.index-shipping-note p {
  margin-bottom: 0;
  font-size: 1rem;
}

.index-faq {
  background-color: var(--color-bg-white);
}

.index-faq-list {
  margin-top: var(--spacing-lg);
}

.index-faq-item {
  background-color: var(--color-bg-light);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  margin-bottom: var(--spacing-md);
  overflow: hidden;
}

.index-faq-item summary {
  padding: var(--spacing-lg);
  cursor: pointer;
  font-weight: 600;
  color: var(--color-primary-dark);
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
  transition: var(--transition);
  min-height: 44px;
}

.index-faq-item summary:hover {
  background-color: var(--color-bg-white);
}

.index-faq-item summary::-webkit-details-marker {
  color: var(--color-primary);
}

.index-faq-item[open] summary {
  background-color: var(--color-bg-white);
  border-bottom: 1px solid var(--color-border);
}

.index-faq-item p {
  padding: 0 var(--spacing-lg) var(--spacing-lg) var(--spacing-lg);
  margin-bottom: 0;
  color: var(--color-text-dark);
}

@media (max-width: 600px) {
  .index-hero .container {
    flex-direction: column;
    gap: var(--spacing-lg);
  }

  .index-hero-content h1 {
    font-size: 1.75rem;
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-price-card-featured {
    transform: scale(1);
  }

  .index-price {
    font-size: 2rem;
  }
}

@media (min-width: 601px) {
  .index-hero-content {
    flex: 0 1 50%;
  }

  .index-hero-image {
    flex: 0 1 40%;
  }
}
